(function(){function init(){var track=document.querySelector('.story-track');if(!track)return;var plane=track.querySelector('.story-plane');var lane=track.querySelector('.story-plane-lane');var cleared=track.parentNode.querySelector('.story-cleared');var stops=Array.prototype.slice.call(track.querySelectorAll('.story-stop'));if(!stops.length)return;if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){track.classList.add('is-underway','is-landed');track.style.setProperty('--story-fill','1');track.style.setProperty('--story-progress','1');stops.forEach(function(s){s.classList.add('is-visible','is-passed')});if(plane)plane.classList.add('is-landed');var t=document.querySelector('.story-timer');if(t){t.classList.add('is-on');var v=t.querySelector('.story-timer-value');if(v)v.textContent='10:00'}return}var reveal=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(!entry.isIntersecting)return;entry.target.classList.add('is-visible');reveal.unobserve(entry.target)})},{rootMargin:'0px 0px -62% 0px',threshold:0});stops.forEach(function(stop){var rect=stop.getBoundingClientRect();if(rect.top<window.innerHeight*0.38&&rect.bottom>0){stop.classList.add('is-visible')}else{reveal.observe(stop)}});var dots=stops.map(function(stop){return stop.querySelector('.story-dot')||stop});var signs=stops.map(function(stop){return stop.querySelector('.story-sign')});var timer=document.querySelector('.story-timer');var timerValue=timer&&timer.querySelector('.story-timer-value');var shownSeconds=-1;var holdingFinish=false;var retireTimer=null;var ticking=false;function update(){ticking=false;var rect=track.getBoundingClientRect();var laneRect=lane?lane.getBoundingClientRect():rect;var wingEdge=0.62;var marker=window.innerHeight/2;var planeH=0;var planeRect=null;if(plane){planeRect=plane.getBoundingClientRect();if(planeRect.height){planeH=planeRect.height;marker=planeRect.top+planeH*wingEdge}}var tops=dots.map(function(dot){return dot.getBoundingClientRect().top});var signRects=signs.map(function(sign){return sign?sign.getBoundingClientRect():null});var fill=Math.max(0,Math.min(1,(marker-rect.top)/rect.height));var travel=laneRect.height-planeH;var progress=travel>0?(marker-(laneRect.top+planeH*wingEdge))/travel:fill;progress=Math.max(0,Math.min(1,progress));track.style.setProperty('--story-fill',fill.toFixed(4));track.style.setProperty('--story-progress',progress.toFixed(4));track.classList.toggle('is-underway',fill>0);if(timerValue){var step=600/(stops.length-1);var seconds;if(marker<=tops[0]){seconds=0}else if(marker>=tops[tops.length-1]){seconds=600}else{seconds=600;for(var k=1;k<tops.length;k++){if(marker<tops[k]){var span=tops[k]-tops[k-1];seconds=(k-1)*step+(span>0?(marker-tops[k-1])/span:0)*step;break}}}var total=Math.round(seconds);if(total!==shownSeconds){shownSeconds=total;var mins=Math.floor(total/60);var secs=total%60;timerValue.textContent=mins+':'+(secs<10?'0':'')+secs}var onScreen=rect.top<window.innerHeight&&progress>0;var arrived=progress>=0.999;if(arrived){if(timerValue)timerValue.textContent='10:00';if(!holdingFinish){holdingFinish=true;timer.classList.add('is-on');clearTimeout(retireTimer);retireTimer=setTimeout(function(){timer.classList.remove('is-on')},1100)}}else{if(holdingFinish){holdingFinish=false;clearTimeout(retireTimer)}timer.classList.toggle('is-on',onScreen)}}stops.forEach(function(stop,i){var passed=tops[i]<=marker;stop.classList.toggle('is-passed',passed);if(passed)stop.classList.add('is-visible');var sr=signRects[i];if(!planeRect||!sr)return;stop.classList.toggle('is-under-plane',sr.bottom>planeRect.top&&sr.top<planeRect.bottom)});var landed=progress>=0.999;if(plane)plane.classList.toggle('is-landed',landed);track.classList.toggle('is-landed',landed)}function onScroll(){if(ticking)return;ticking=true;window.requestAnimationFrame(update)}window.addEventListener('scroll',onScroll,{passive:true});window.addEventListener('resize',onScroll,{passive:true});update()}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init)}else{init()}}())
